    avg_demand = np.mean(demand)
    std_demand = np.std(demand)
    dynamic_threshold = max(0.7 * capacity, avg_demand + 0.5 * std_demand)
    optimal_sum = capacity

    for i in range(n):
        for j in range(n):
            if i == j:
                heuristics_matrix[i][j] = 0.0
            else:
                pair_sum = demand[i] + demand[j]
                if pair_sum > optimal_sum:
                    heuristics_matrix[i][j] = 0.0
                else:
                    diff = optimal_sum - pair_sum
                    size_ratio = min(demand[i], demand[j]) / max(demand[i], demand[j])
                    balance_weight = (1.0 - (diff / capacity)) ** 2
                    variability_score = np.exp(-(demand[i] - demand[j]) ** 2 / (2 * std_demand ** 2))

                    if diff == 0:
                        heuristics_matrix[i][j] = 1.0 + np.log(1 + avg_demand) + balance_weight + variability_score
                    else:
                        score = (1.0 / (diff ** 1.5)) * balance_weight * variability_score
                        heuristics_matrix[i][j] = score if pair_sum >= dynamic_threshold else 0.0

    return heuristics_matrix

